{
  "name": "@tiuxo/opencode-openrgb",
  "version": "0.1.1",
  "description": "Ambient status lighting for opencode via OpenRGB. Mirrors session state onto your RGB hardware.",
  "type": "module",
  "license": "BSD-3-Clause",
  "author": "Brian Clemens <brian@tiuxo.com>",
  "repository": {
    "type": "git",
    "url": "git+https://git.tiuxo.com/brian/opencode-openrgb.git"
  },
  "homepage": "https://git.tiuxo.com/brian/opencode-openrgb",
  "bugs": {
    "url": "https://git.tiuxo.com/brian/opencode-openrgb/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "openrgb",
    "rgb",
    "lighting",
    "ambient",
    "status"
  ],
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "src",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit && tsc -p tsconfig.scripts.json",
    "check": "bun run typecheck && bun test",
    "probe": "bun scripts/probe.ts",
    "selftest": "bun scripts/selftest.ts",
    "simulate": "bun scripts/simulate.ts"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.2.7",
    "@types/bun": "^1.4.0",
    "@types/node": "^24.12.2",
    "typescript": "^5.8.2"
  },
  "engines": {
    "opencode": ">=2.0.0"
  }
}
